function stOverlay() {
  const o = document.createElement('div');
  o.id = 'selfTestOverlay';
  o.style.cssText = 'position:fixed;inset:0;z-index:99999;background:#0b0c0e;color:#e8d9b8;overflow:auto;padding:16px;font:12px/1.5 ui-monospace,Consolas,monospace';
  o.innerHTML = '<div style="max-width:760px;margin:0 auto"><div style="font-size:15px;font-weight:600;margin-bottom:4px">irlab self-test</div><div id="stGpu" style="color:#a89372;margin-bottom:10px"></div><div id="stStatus" style="margin-bottom:10px">Starting\u2026</div><div id="stRows"></div><div id="stSummary" style="margin:14px 0;font-size:14px;font-weight:600"></div><div style="display:flex;gap:10px;flex-wrap:wrap"><button id="stCopy" type="button" style="display:none">Copy report</button><button id="stBack" type="button">Back to editor</button></div></div>';
  document.body.appendChild(o);
  $('stBack').onclick = () => { location.href = location.pathname; };
  try {
    const gl = engine && engine.gl, ext = gl && gl.getExtension('WEBGL_debug_renderer_info');
    $('stGpu').textContent = ext ? gl.getParameter(ext.UNMASKED_RENDERER_WEBGL) : 'GPU: not reported';
  } catch (e) {}
  return {
    status: t => { $('stStatus').textContent = t; },
    row: (ok, text) => { const d = document.createElement('div'); d.style.color = ok === true ? '#9fd6a8' : ok === false ? '#ff8a70' : '#e8d9b8'; d.textContent = (ok === true ? 'ok    ' : ok === false ? 'FAIL  ' : '      ') + text; $('stRows').appendChild(d); d.scrollIntoView({ block: 'end' }); },
    summary: (t, good) => { const e = $('stSummary'); e.textContent = t; e.style.color = good ? '#9fd6a8' : '#ff8a70'; },
  };
}
async function runSelfTest() {
  const record = /[?&]record(&|=|$)/.test(location.search);
  window.__stDone = false;
  const ui = stOverlay(), lines = [];
  const say = (ok, t) => { lines.push((ok === true ? 'ok    ' : ok === false ? 'FAIL  ' : '      ') + t); ui.row(ok, t); };
  try {
    if (!window.DecompressionStream && !record) throw new Error('This browser cannot decompress the baseline (needs a recent Chrome, Safari 16.4+ or Firefox).');
    let golden = null;
    if (!record) {
      const raw = await stInflate(ST_GOLDEN.b64), sz = ST_GW * ST_GH * 3;
      golden = {}; ST_GOLDEN.names.forEach((n, i) => { golden[n] = raw.subarray(i * sz, (i + 1) * sz); });
    }
    const newGrids = {}; let cur = null, problems = 0;
    const ensure = async img => { if (cur === img) return; ui.status('Loading test image: ' + img); await stLoadFixture(img); cur = img; };
    say(null, 'Baseline comparison (OKLab \u0394E; mean tol ' + ST_MEAN_TOL + ', 99th pct tol ' + ST_P99_TOL + ')');
    const order = ST_CASES.slice().sort((a, b) => (a.img === b.img ? 0 : a.img === 'scene' ? -1 : 1));
    for (const c of order) {
      await ensure(c.img); ui.status('Running ' + c.name + '\u2026');
      const g = stGrid(c); newGrids[c.name] = g;
      if (!record) {
        const base = golden[c.name];
        if (!base) { say(false, c.name.padEnd(28) + ' no baseline'); problems++; }
        else { const d = stDeltaE(base, g), ok = d.mean <= ST_MEAN_TOL && d.p99 <= ST_P99_TOL; if (!ok) problems++; say(ok, c.name.padEnd(28) + ' mean ' + d.mean.toFixed(5) + '  p99 ' + d.p99.toFixed(4) + '  max ' + d.max.toFixed(4)); }
      }
      await new Promise(r => setTimeout(r, 0));
    }
    if (record) {
      const sz = ST_GW * ST_GH * 3, all = new Uint8Array(ST_CASES.length * sz);
      ST_CASES.forEach((c, i) => all.set(newGrids[c.name], i * sz));
      window.__stRecord = { names: ST_CASES.map(c => c.name), b64: await stDeflate(all) };
      say(true, 'baseline recorded for ' + ST_CASES.length + ' cases');
    }
    say(null, ''); say(null, 'Rules that must always hold');
    const props = stProperties().sort((a, b) => (a.img === b.img ? 0 : a.img === 'scene' ? -1 : 1));
    for (const pr of props) {
      await ensure(pr.img); ui.status('Checking: ' + pr.name);
      let r; try { r = pr.run(); } catch (e) { r = { ok: false, detail: String(e) }; }
      if (!r.ok) problems++;
      say(r.ok, pr.name + '  ' + JSON.stringify(r.detail));
      await new Promise(r2 => setTimeout(r2, 0));
    }
    const good = problems === 0;
    ui.status('Done.');
    ui.summary(record ? 'Baseline recorded' : (good ? 'All good' : problems + ' problem(s)'), good);
    lines.push(good ? 'All good' : problems + ' problem(s)');
    window.__stResults = { problems: problems, lines: lines };
  } catch (e) {
    ui.status('Self-test could not run'); ui.summary(String(e && e.message || e), false);
    lines.push('ERROR ' + String(e && e.message || e)); window.__stResults = { problems: -1, lines: lines };
  }
  const gpu = $('stGpu').textContent;
  const cp = $('stCopy'); cp.style.display = '';
  cp.onclick = async () => {
    const text = 'irlab self-test\nGPU: ' + gpu + '\n' + navigator.userAgent + '\n\n' + lines.join('\n');
    try { await navigator.clipboard.writeText(text); cp.textContent = 'Copied'; }
    catch (e) { const ta = document.createElement('textarea'); ta.value = text; document.body.appendChild(ta); ta.select(); try { document.execCommand('copy'); cp.textContent = 'Copied'; } catch (e2) { cp.textContent = 'Copy failed'; } document.body.removeChild(ta); }
  };
  window.__stDone = true;
}
// this file is fetched separately (see src/i18n.js), so the page may already have finished loading
if (SELFTEST) { if (document.readyState === 'complete') setTimeout(runSelfTest, 400); else window.addEventListener('load', () => { setTimeout(runSelfTest, 400); }); }
